import { SimplexNoise, type SimplexNoiseProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#12121a", "#3a3a5c", "#52527a", "#8a8a95"];

interface ShaderSimplexNoiseProps
  extends Omit<SimplexNoiseProps, "frame" | "ref"> {}

function ShaderSimplexNoiseBase({
  speed = 1,
  colors = NEUTRAL_COLORS,
  stepsPerColor = 2,
  softness = 0.1,
  className,
  ...rest
}: ShaderSimplexNoiseProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-simplex-noise"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <SimplexNoise
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colors={colors}
        stepsPerColor={stepsPerColor}
        softness={softness}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  stepsPerColor: {
    type: "number",
    min: 1,
    max: 6,
    step: 1,
    default: 2,
    description: "Steps",
    hiddenFromList: false,
  },
  softness: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.1,
    description: "Softness",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","stepsPerColor","softness"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  stepsPerColor: 2,
  softness: 0.1,
};

type ShaderSimplexNoiseElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderSimplexNoiseBase>;

const ShaderSimplexNoiseInner = forwardRef<
  HTMLDivElement,
  ShaderSimplexNoiseElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderSimplexNoise>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderSimplexNoiseBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderSimplexNoiseBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderSimplexNoise = Interactive.withSchema({
  Component: ShaderSimplexNoiseInner,
  componentName: "<ShaderSimplexNoise>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
